import numpy as np
from scipy.optimize import brentq
import math

def a_closed(a1, n):
    alpha = a1 / (a1 + 1)
    return a1 * alpha**(n-1)

def b_closed(b1, n):
    if n == 1:
        return b1
    num = 1.0
    for k in range(n):
        num *= (b1 + 2*k)
    den = 1.0
    for k in range(n-1):
        den *= (b1 + 2*k + 1)
    return num / den

# Use log-space for a_closed to avoid overflow
def a_closed_log(a1, n):
    return math.log(a1) + (n-1)*(math.log(a1) - math.log(a1+1))

def b_closed_log(b1, n):
    if n == 1:
        return math.log(b1)
    s = 0.0
    for k in range(n):
        s += math.log(b1 + 2*k)
    for k in range(n-1):
        s -= math.log(b1 + 2*k + 1)
    return s

print("Asymptotic analysis:")
for b1 in [100, 500, 1000, 5000, 10000, 50000, 100000, 500000, 1000000]:
    log_b99 = b_closed_log(b1, 99)
    # Solve log(a1) + 99*(log(a1) - log(a1+1)) = log_b99
    def eq(a1):
        return a_closed_log(a1, 100) - log_b99
    lo, hi = 1.0, 10*b1 + 10000
    a1 = brentq(eq, lo, hi)
    diff = a1 - b1
    threshold = 197 - 1.0/(b1+198)
    gap = threshold - diff
    print(f"b1={b1:>8d}: a1-b1={diff:.8f}, threshold={threshold:.8f}, gap={gap:.10f}, gap*(b1+198)={gap*(b1+198):.6f}")

print("\nDirect comparison a100/(a1+1) vs b100/(b1+199):")
for b1 in [0.01, 0.1, 1.0, 10.0, 100.0, 1000.0, 10000.0, 100000.0]:
    log_b99 = b_closed_log(b1, 99)
    a1 = brentq(lambda x: a_closed_log(x, 100) - log_b99, 1.0, 10*b1 + 10000)
    a100 = a_closed(a1, 100)
    b100 = b_closed(b1, 100)
    lhs = a100 / (a1 + 1)
    rhs = b100 / (b1 + 199)
    print(f"b1={b1:>10.2f}: a100/(a1+1)={lhs:.10f}, b100/(b1+199)={rhs:.10f}, diff={lhs-rhs:.10f}")
